import{_ as p,a0 as o,w as d,s as h,ao as i,I as a,x as n,a1 as l,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Bash 脚本中添加注释 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Bash 脚本中添加注释 | LCTT (202310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Bash 脚本中添加注释 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Bash 脚本中添加注释 | LCTT (202310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202310/20231010 How to Add Comments in Bash Scripts","title":"如何在 Bash 脚本中添加注释","tag":"202310","desc":""},"relativePath":"202310/20231010 How to Add Comments in Bash Scripts.md","filePath":"[post].md"}'),r={name:"202310/20231010 How to Add Comments in Bash Scripts.md"};function u(b,s,g,m,c,k){const e=o("Link");return d(),h("div",null,[s[28]||(s[28]=i(`<h1 id="如何在-bash-脚本中添加注释" tabindex="-1">如何在 Bash 脚本中添加注释 <a class="header-anchor" href="#如何在-bash-脚本中添加注释" aria-label="Permalink to “如何在 Bash 脚本中添加注释”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202310/19/113658dld7b9987xa89l99.jpg" alt=""></p><blockquote><p>你有要说明的地方吗？请将它们添加到你的 Bash 脚本中。</p></blockquote><p>在 Bash 脚本中添加注释是保持代码整洁且易于理解的最有效方法之一。</p><p>你可能会问为什么。</p><p>假设你的脚本包含一个复杂的正则表达式或多个复杂的代码块，在这种情况下，你可以添加注释，以便其他开发人员或你可以了解该代码块的含义。</p><p>注释掉部分代码也有助于调试脚本。</p><p>在本教程中，我将引导你了解在 Bash 脚本中添加注释的三种方法：</p><ul><li>单行注释</li><li>行内评论</li><li>多行注释</li></ul><p>那么让我们从第一个开始。</p><h3 id="bash-中的单行注释" tabindex="-1">Bash 中的单行注释 <a class="header-anchor" href="#bash-中的单行注释" aria-label="Permalink to “Bash 中的单行注释”">​</a></h3><p>要添加单行注释，你必须将哈希符号（<code>#</code>）放在行的开头并编写注释。</p><p>这是一个简单的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span># This is a comment</span></span>
<span class="line"><span>echo &quot;Hello, World!&quot;</span></span></code></pre></div><p>执行时，注释将被忽略，当我执行上面的命令时，它看起来像这样：</p><p><img src="https://itsfoss.com/content/images/2023/10/Use-single-line-comments-in-bash.png" alt=""></p>`,16)),a("blockquote",null,[a("p",null,[s[1]||(s[1]=n("💡 ",-1)),s[2]||(s[2]=a("code",null,"#",-1)),s[3]||(s[3]=n(" 注释规则的唯一例外是脚本开头的 ",-1)),s[4]||(s[4]=a("code",null,"#!/bin/bash",-1)),s[5]||(s[5]=n(" 行。它称为 ",-1)),l(e,{href:"https://linux.cn/article-3664-1.html"},{default:t(()=>[...s[0]||(s[0]=[n("释伴",-1)])]),_:1}),s[6]||(s[6]=n("，用于指定运行脚本时要使用的解释器。有不同的 Shell，语法也可能不同。因此，一个好的做法是指定脚本是为哪个 Shell 编写的。例如，如果是 ksh，则可以使用 ",-1)),s[7]||(s[7]=a("code",null,"#!/bin/ksh",-1)),s[8]||(s[8]=n(".",-1))])]),s[29]||(s[29]=i(`<h3 id="bash-脚本中的内联注释" tabindex="-1">Bash 脚本中的内联注释 <a class="header-anchor" href="#bash-脚本中的内联注释" aria-label="Permalink to “Bash 脚本中的内联注释”">​</a></h3><p>或者，你可以将注释放在代码块内以记录该特定行的用途。</p><blockquote><p>🚧 <code>#</code> 之后的任何内容在该行结束之前都不会执行，因此请确保在代码末尾添加注释。</p></blockquote><p>这是一个简单的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>echo &quot;Hello, World!&quot; #Prints hello world</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/10/How-to-use-the-single-line-comments-in-bash.png" alt=""></p><h3 id="bash-中的多行注释" tabindex="-1">Bash 中的多行注释 <a class="header-anchor" href="#bash-中的多行注释" aria-label="Permalink to “Bash 中的多行注释”">​</a></h3><blockquote><p>🚧 Bash 中没有内置的多行注释功能。但是，有一些解决方法可以实现多行注释效果。</p></blockquote><p>顾名思义，Bash 脚本中的多行注释允许你在多行中编写注释，或者通过将它们放在多行注释部分来阻止执行代码块：</p>`,9)),a("ol",null,[s[11]||(s[11]=a("li",null,[n("在每行的开头使用 "),a("code",null,"#")],-1)),a("li",null,[l(e,{href:"https://stackoverflow.com/questions/3224878/what-is-the-purpose-of-the-colon-gnu-bash-builtin"},{default:t(()=>[...s[9]||(s[9]=[n("冒号表示法",-1)])]),_:1}),s[10]||(s[10]=n("（使用冒号后跟单引号）",-1))]),s[12]||(s[12]=a("li",null,[n("现场文档（使用 "),a("code",null,"<<"),n(" 后跟分隔符）")],-1))]),s[30]||(s[30]=i(`<p>那么让我们从第一个开始。</p><h4 id="_1、对块注释的每一行使用" tabindex="-1">1、对块注释的每一行使用 <code>#</code> <a class="header-anchor" href="#_1、对块注释的每一行使用" aria-label="Permalink to “1、对块注释的每一行使用 #”">​</a></h4><p>如果你的目的是解释脚本的一部分，我建议使用此方法。毕竟，<code>#</code> 才是真正的注释功能。</p><p>这也是许多开发人员使用的方法。</p><p>假设你必须在一开始就解释脚本的用途、作者信息或许可信息。你可以这样写：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>######################################</span></span>
<span class="line"><span>## This script is used for scanning ##</span></span>
<span class="line"><span>## local network                    ##</span></span>
<span class="line"><span>## Licensed under GPL 2.0           ##</span></span>
<span class="line"><span>######################################</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这个 Bash 脚本的其它部分……</span></span></code></pre></div><p>当你想说明 Bash 脚本的行为方式时这不错。如果你正在调试 Bash 脚本并希望隐藏部分脚本，则在所需代码的每一行开头添加 <code>#</code> 并在调试后将其删除是一项耗时的任务。</p><p>接下来的两节将帮助你做到这一点。</p><h4 id="_2、冒号表示法" tabindex="-1">2、冒号表示法 <a class="header-anchor" href="#_2、冒号表示法" aria-label="Permalink to “2、冒号表示法”">​</a></h4><p>要使用冒号表示法，请在 <code>: &#39;</code> 和结束的 <code>&#39;</code> 之间编写块注释，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>: &#39;</span></span>
<span class="line"><span>This is how you can use colon notation</span></span>
<span class="line"><span>And this line too will be ignored</span></span>
<span class="line"><span>&#39;</span></span>
<span class="line"><span>echo &quot;GOODBYE&quot;</span></span></code></pre></div><p>当你执行上面的脚本时，它应该只打印 <code>GOODBYE</code>。</p><p><img src="https://itsfoss.com/content/images/2023/10/Use-multi-line-comments-using-colon-notation-in-bash.png" alt=""></p><h4 id="_3、现场文档" tabindex="-1">3、现场文档 <a class="header-anchor" href="#_3、现场文档" aria-label="Permalink to “3、现场文档”">​</a></h4><p>到目前为止，这是在 Bash 中编写多行注释的最流行的方法，你可以使用 <code>&lt;&lt;</code> 后跟分隔符（一组用于指定注释开始和结束的字符）。</p><p>（LCTT 译注：在编程领域，“<strong>here document</strong>” 是一个常见的术语，特指在脚本语言（如 Perl、Bash）中，能够直接在代码内部嵌入并处理一个数据块或文本串的技术。尽管传统上我们将它翻译为“嵌入式文档” 或不翻译，但这个译法似乎并不能完全地体现出原文的感觉和含义。为了让这个概念变得更为直观和易理解，我们建议将 “here document” 翻译为 “<strong>现场文档</strong>”。“现场”相比于“嵌入式”，更好的传达了文档就在代码的当前位置，或代码“现场”的含义。这样的译法也与原文 “here document” 中 “here”（这里）的含义更为契合。我们希望这个译法能够在未来得到更广泛的使用和认可，让编程的世界因语言的精准而变得更美好。PS., 该译法和解释得到了 ChatGPT 的建议和生成。）</p><p>使用方法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;&lt;DELIMITER</span></span>
<span class="line"><span>Comment line 1</span></span>
<span class="line"><span>Comment line 2</span></span>
<span class="line"><span>DELIMITER</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;Hello, World!&quot;</span></span></code></pre></div><p>还困惑吗？ 这是一个简单的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;&lt;COMMENT</span></span>
<span class="line"><span>This is a multi-line comment using a here document.</span></span>
<span class="line"><span>You can add as many lines as you want between &lt;&lt;COMMENT and the terminating keyword.</span></span>
<span class="line"><span>This block won&#39;t be executed by the shell.</span></span>
<span class="line"><span>COMMENT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;Hello, World!&quot;</span></span></code></pre></div><p>在上面的示例中，我使用了 <code>COMMENT</code> 作为分隔符，但你可以使用任何内容，但要确保它从注释中脱颖而出，否则会造成混乱。</p><p>当我执行上面的脚本时，它给出了以下输出：</p><p><img src="https://itsfoss.com/content/images/2023/10/Use-multi-line-comments-in-bash-using----and-delimeter.png" alt=""></p><p>正如你所看到的，它忽略了从 <code>&lt;&lt;COMMENT</code> 到 <code>COMMENT</code> 的所有内容。</p><p>我希望本指南对你有所帮助。</p><p><em>（题图：MJ/7c2a3ef4-5256-405e-b757-23e0ba1f0bc5）</em></p><hr>`,27)),a("p",null,[s[14]||(s[14]=n("via: ",-1)),l(e,{href:"https://itsfoss.com/bash-comments/"},{default:t(()=>[...s[13]||(s[13]=[n("https://itsfoss.com/bash-comments/",-1)])]),_:1})]),a("p",null,[s[19]||(s[19]=n("作者：",-1)),l(e,{href:"https://itsfoss.com/author/sagar/"},{default:t(()=>[...s[15]||(s[15]=[n("Sagar Sharma",-1)])]),_:1}),s[20]||(s[20]=n(" 选题：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[16]||(s[16]=[n("lujun9972",-1)])]),_:1}),s[21]||(s[21]=n(" 译者：",-1)),l(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[17]||(s[17]=[n("geekpi",-1)])]),_:1}),s[22]||(s[22]=n(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[18]||(s[18]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[25]||(s[25]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[23]||(s[23]=[n("LCTT",-1)])]),_:1}),s[26]||(s[26]=n(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:t(()=>[...s[24]||(s[24]=[n("Linux中国",-1)])]),_:1}),s[27]||(s[27]=n(" 荣誉推出",-1))])])}const B=p(r,[["render",u]]);export{C as __pageData,B as default};
